WITH base AS (
  SELECT sch.school, sch.district, sch.county, sc.avgscrwrite
  FROM satscores sc JOIN schools sch ON sch.cdscode = sc.cds
  WHERE sch.statustype = 'Closed' AND sc.avgscrwrite IS NOT NULL AND sc.rtype = 'S'
), ranked AS (
  SELECT DISTINCT avgscrwrite FROM base ORDER BY avgscrwrite DESC LIMIT 1 OFFSET 1
)
SELECT b.school, b.district, b.county, b.avgscrwrite
FROM base b JOIN ranked r ON b.avgscrwrite = r.avgscrwrite
ORDER BY b.school;

