WITH latest AS (
  SELECT player_api_id, overall_rating, defensive_work_rate,
         ROW_NUMBER() OVER (PARTITION BY player_api_id ORDER BY date DESC, id DESC) rn
  FROM player_attributes
  WHERE date <= '2013-07-12 00:00:00'
), cur AS (
  SELECT * FROM latest WHERE rn = 1 AND defensive_work_rate IN ('low','medium','high')
)
SELECT ROUND(((SELECT overall_rating FROM cur WHERE player_api_id = 30700) - AVG(overall_rating)) * 100.0 / AVG(overall_rating), 2) AS pct
FROM cur;

